## Code Example
```javascript
// Pseudo-test sketch using Playwright
const { test, expect } = require('@playwright/test');

test.describe('E2E Food Delivery Flow', () => {
  let wsServer, testData;

  test.beforeAll(async () => {
    wsServer = await startMockWebSocketServer();
    testData = await seedDeterministicTestData();
  });

  test('complete delivery flow with driver tracking', async ({ page }) => {
    const driverUpdates = [];

    // Simulate real-time driver location stream
    wsServer.on('driver-location', (data) => driverUpdates.push(data));

    // 1. Place order
    await page.goto('/order');
    await page.fill('#address', testData.address);
    await page.click('#place-order');
    const orderId = await expectOrderConfirmed(page);

    // 2. Restaurant accepts
    await wsServer.emit('order-status', { orderId, status: 'accepted' });
    await expectOrderStatus(page, 'accepted');

    // 3. Driver assigned
    await wsServer.emit('driver-assigned', { orderId, driver: testData.driver });
    await expectDriverAssigned(page, testData.driver);

    // 4. Verify location/ETA streaming
    await wsServer.emit('driver-location', { lat: 40.7128, lng: -74.0060, eta: 10 });
    await expectETA(page, '10 min');

    // 5. Payment processed
    await stubPaymentAPI({ orderId, status: 'success' });
    await expectPaymentStatus(page, 'paid');

    // 6. Delivery completes
    await wsServer.emit('order-status', { orderId, status: 'delivered' });
    await expectOrderStatus(page, 'delivered');

    // Verify idempotent event handling
    await wsServer.emit('order-status', { orderId, status: 'delivered' });
    expect(driverUpdates).toHaveLength(1); // No duplicate processing

    // Verify eventual consistency
    await expectExternalServiceSynced(orderId);
  });

  test('handles driver disconnect gracefully', async ({ page }) => {
    const orderId = await placeOrder(page);
    await wsServer.simulateDisconnect();

    await expectReconnectionLogic(page);
    await expectDriverReassigned(page);
  });
});
```

